INSERT INTO textes (id, code, titre, date_adoption) VALUES
(1, 'STATUTS', 'Statuts de l''AMAC - Edition 2013', '2013-12-24'),
(2, 'RI', 'Règlement Intérieur de l''AMAC - Edition 2013', '2013-12-24');
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (1, 1, 1, 'Article 1', 'Constitution', 'Il est constitué entre les adhérents aux présents statuts une association régie par la loi n° 60-315 du 21 septembre 1960 relative aux associations, dénommée Les Amis de la Musique Afro-Cubaine (AMAC).', 'TITRE I - CONSTITUTION - OBJET - DUREE - SIEGE', NULL, 1);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (2, 1, 2, 'Article 2', 'Article 2', 'Contenu standard de l''article 2 des statuts de l''AMAC. Conformément aux dispositions en vigueur, les membres s''engagent à respecter l''objet de l''association et à participer activement à ses activités pour promouvoir la musique afro-cubaine.', 'TITRE I - CONSTITUTION - OBJET - DUREE - SIEGE', NULL, 2);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (3, 1, 3, 'Article 3', 'Article 3', 'Contenu standard de l''article 3 des statuts de l''AMAC. Conformément aux dispositions en vigueur, les membres s''engagent à respecter l''objet de l''association et à participer activement à ses activités pour promouvoir la musique afro-cubaine.', 'TITRE I - CONSTITUTION - OBJET - DUREE - SIEGE', NULL, 3);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (4, 1, 4, 'Article 4', 'Article 4', 'Contenu standard de l''article 4 des statuts de l''AMAC. Conformément aux dispositions en vigueur, les membres s''engagent à respecter l''objet de l''association et à participer activement à ses activités pour promouvoir la musique afro-cubaine.', 'TITRE I - CONSTITUTION - OBJET - DUREE - SIEGE', NULL, 4);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (5, 1, 5, 'Article 5', 'Régime juridique', 'L''association est régie par la loi n° 60-315 du 21 septembre 1960 relative aux associations en Côte d''Ivoire.', 'TITRE I - CONSTITUTION - OBJET - DUREE - SIEGE', NULL, 5);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (6, 1, 6, 'Article 6', 'Moyens d''action', 'Les moyens d''action de l''association sont : l''organisation de concerts, de conférences, de séminaires, d''ateliers de danse et de percussion, et toute autre activité culturelle favorisant la musique afro-cubaine.', 'TITRE II - ACQUISITION ET PERTE DE LA QUALITE DE MEMBRE', NULL, 6);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (7, 1, 7, 'Article 7', 'Article 7', 'Contenu standard de l''article 7 des statuts de l''AMAC. Conformément aux dispositions en vigueur, les membres s''engagent à respecter l''objet de l''association et à participer activement à ses activités pour promouvoir la musique afro-cubaine.', 'TITRE II - ACQUISITION ET PERTE DE LA QUALITE DE MEMBRE', NULL, 7);
