INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (12, 1, 12, 'Article 12', 'Article 12', 'Contenu standard de l''article 12 des statuts de l''AMAC. Conformément aux dispositions en vigueur, les membres s''engagent à respecter l''objet de l''association et à participer activement à ses activités pour promouvoir la musique afro-cubaine.', 'TITRE II - ACQUISITION ET PERTE DE LA QUALITE DE MEMBRE', NULL, 12);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (13, 1, 13, 'Article 13', 'Perte de la qualité de membre et droit de vote des fondateurs', 'La qualité de membre se perd par démission, exclusion ou décès. Les membres fondateurs ne disposent pas du droit de vote lors des assemblées générales ordinaires et extraordinaires de l''AMAC, disposant uniquement d''une voix consultative.', 'TITRE III - DROITS AND DEVOIRS DES MEMBRES', NULL, 13);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (14, 1, 14, 'Article 14', 'Droits et devoirs', 'Chaque membre a le droit de participer aux activités de l''association. Les devoirs des membres s''exercent conformément à l''art. 6 pour la devise et l''identité visuelle de l''association.', 'TITRE III - DROITS AND DEVOIRS DES MEMBRES', NULL, 14);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (15, 1, 15, 'Article 15', 'Article 15', 'Contenu standard de l''article 15 des statuts de l''AMAC. Conformément aux dispositions en vigueur, les membres s''engagent à respecter l''objet de l''association et à participer activement à ses activités pour promouvoir la musique afro-cubaine.', 'TITRE III - DROITS AND DEVOIRS DES MEMBRES', NULL, 15);
