INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (17, 1, 17, 'Article 17', 'Article 17', 'Contenu standard de l''article 17 des statuts de l''AMAC. Conformément aux dispositions en vigueur, les membres s''engagent à respecter l''objet de l''association et à participer activement à ses activités pour promouvoir la musique afro-cubaine.', 'TITRE IV - ORGANISATION GENERALE', 'CHAPITRE I - L''ASSEMBLEE GENERALE', 17);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (18, 1, 18, 'Article 18', 'Article 18', 'Contenu standard de l''article 18 des statuts de l''AMAC. Conformément aux dispositions en vigueur, les membres s''engagent à respecter l''objet de l''association et à participer activement à ses activités pour promouvoir la musique afro-cubaine.', 'TITRE IV - ORGANISATION GENERALE', 'CHAPITRE I - L''ASSEMBLEE GENERALE', 18);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (19, 1, 19, 'Article 19', 'Article 19', 'Contenu standard de l''article 19 des statuts de l''AMAC. Conformément aux dispositions en vigueur, les membres s''engagent à respecter l''objet de l''association et à participer activement à ses activités pour promouvoir la musique afro-cubaine.', 'TITRE IV - ORGANISATION GENERALE', 'CHAPITRE I - L''ASSEMBLEE GENERALE', 19);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (20, 1, 20, 'Article 20', 'Article 20', 'Contenu standard de l''article 20 des statuts de l''AMAC. Conformément aux dispositions en vigueur, les membres s''engagent à respecter l''objet de l''association et à participer activement à ses activités pour promouvoir la musique afro-cubaine.', 'TITRE IV - ORGANISATION GENERALE', 'CHAPITRE I - L''ASSEMBLEE GENERALE', 20);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (21, 1, 21, 'Article 21', 'Quorum de l''Assemblée Générale', 'L''assemblée générale ne peut valablement délibérer que si elle réunit les 2/3 de ses membres. Si ce quorum n''est pas atteint, une nouvelle assemblée est convoquée à un mois d''intervalle et peut délibérer quel que soit le nombre de présents.', 'TITRE IV - ORGANISATION GENERALE', 'CHAPITRE I - L''ASSEMBLEE GENERALE', 21);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (22, 1, 22, 'Article 22', 'Droit de procuration', 'Le vote par procuration est autorisé uniquement pour les membres fondateurs empêchés. Nul ne peut être porteur de plus de deux procurations.', 'TITRE IV - ORGANISATION GENERALE', 'CHAPITRE II - L''ORGANISME DE CONTROLE', 22);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (23, 1, 23, 'Article 23', 'Composition et rôle du Comité de Contrôle', 'Le Comité de Contrôle est composé principalement de membres fondateurs. Il est chargé de veiller à l''application des statuts, d''organiser les élections et peut s''autosaisir de tout conflit interne ou suspicion de mauvaise gestion.', 'TITRE IV - ORGANISATION GENERALE', 'CHAPITRE II - L''ORGANISME DE CONTROLE', 23);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (24, 1, 24, 'Article 24', 'Article 24', 'Contenu standard de l''article 24 des statuts de l''AMAC. Conformément aux dispositions en vigueur, les membres s''engagent à respecter l''objet de l''association et à participer activement à ses activités pour promouvoir la musique afro-cubaine.', 'TITRE IV - ORGANISATION GENERALE', 'CHAPITRE III - L''ORGANISATION ADMINISTRATIVE', 24);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (25, 1, 25, 'Article 25', 'Article 25', 'Contenu standard de l''article 25 des statuts de l''AMAC. Conformément aux dispositions en vigueur, les membres s''engagent à respecter l''objet de l''association et à participer activement à ses activités pour promouvoir la musique afro-cubaine.', 'TITRE IV - ORGANISATION GENERALE', 'CHAPITRE III - L''ORGANISATION ADMINISTRATIVE', 25);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (26, 1, 26, 'Article 26', 'Composition du Bureau Exécutif National (BEN)', 'Le BEN comprend un Président et 9 autres membres nommés directement par le Président seul, y compris un Vice-Président, un Secrétaire Général et un Trésorier Général.', 'TITRE V - ADMINISTRATION ET FONCTIONNEMENT', 'CHAPITRE III - L''ORGANISATION ADMINISTRATIVE', 26);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (27, 1, 27, 'Article 27', 'Article 27', 'Contenu standard de l''article 27 des statuts de l''AMAC. Conformément aux dispositions en vigueur, les membres s''engagent à respecter l''objet de l''association et à participer activement à ses activités pour promouvoir la musique afro-cubaine.', 'TITRE V - ADMINISTRATION ET FONCTIONNEMENT', 'CHAPITRE III - L''ORGANISATION ADMINISTRATIVE', 27);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (28, 1, 28, 'Article 28', 'Article 28', 'Contenu standard de l''article 28 des statuts de l''AMAC. Conformément aux dispositions en vigueur, les membres s''engagent à respecter l''objet de l''association et à participer activement à ses activités pour promouvoir la musique afro-cubaine.', 'TITRE V - ADMINISTRATION ET FONCTIONNEMENT', 'CHAPITRE III - L''ORGANISATION ADMINISTRATIVE', 28);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (29, 1, 29, 'Article 29', 'Majorité requise pour les décisions du BEN', 'Les décisions du Bureau Exécutif National sont prises à la majorité de 51 % des suffrages exprimés. En cas de partage des voix, celle du Président est prépondérante.', 'TITRE V - ADMINISTRATION ET FONCTIONNEMENT', 'CHAPITRE III - L''ORGANISATION ADMINISTRATIVE', 29);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (30, 1, 30, 'Article 30', 'Article 30', 'Contenu standard de l''article 30 des statuts de l''AMAC. Conformément aux dispositions en vigueur, les membres s''engagent à respecter l''objet de l''association et à participer activement à ses activités pour promouvoir la musique afro-cubaine.', 'TITRE V - ADMINISTRATION ET FONCTIONNEMENT', 'CHAPITRE III - L''ORGANISATION ADMINISTRATIVE', 30);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (31, 1, 31, 'Article 31', 'Article 31', 'Contenu standard de l''article 31 des statuts de l''AMAC. Conformément aux dispositions en vigueur, les membres s''engagent à respecter l''objet de l''association et à participer activement à ses activités pour promouvoir la musique afro-cubaine.', 'TITRE V - ADMINISTRATION ET FONCTIONNEMENT', 'CHAPITRE III - L''ORGANISATION ADMINISTRATIVE', 31);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (32, 1, 32, 'Article 32', 'Attributions du Président', 'Le Président est le représentant légal de l''association. Il nomme seul les 9 autres membres du BEN et peut déléguer ses pouvoirs au Vice-Président comme prévu à l''article 26 des statuts.', 'TITRE V - ADMINISTRATION ET FONCTIONNEMENT', 'CHAPITRE III - L''ORGANISATION ADMINISTRATIVE', 32);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (33, 1, 33, 'Article 33', 'Article 33', 'Contenu standard de l''article 33 des statuts de l''AMAC. Conformément aux dispositions en vigueur, les membres s''engagent à respecter l''objet de l''association et à participer activement à ses activités pour promouvoir la musique afro-cubaine.', 'TITRE V - ADMINISTRATION ET FONCTIONNEMENT', 'CHAPITRE III - L''ORGANISATION ADMINISTRATIVE', 33);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (34, 1, 34, 'Article 34', 'Article 34', 'Contenu standard de l''article 34 des statuts de l''AMAC. Conformément aux dispositions en vigueur, les membres s''engagent à respecter l''objet de l''association et à participer activement à ses activités pour promouvoir la musique afro-cubaine.', 'TITRE V - ADMINISTRATION ET FONCTIONNEMENT', 'CHAPITRE III - L''ORGANISATION ADMINISTRATIVE', 34);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (35, 1, 35, 'Article 35', 'Mandat du Bureau Exécutif', 'Le mandat du Bureau Exécutif est calqué sur celui du Président, soit une durée de 5 ans renouvelable. Il comprend également le 1er Vice-Président qui seconde le Président.', 'TITRE V - ADMINISTRATION ET FONCTIONNEMENT', 'CHAPITRE III - L''ORGANISATION ADMINISTRATIVE', 35);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (36, 1, 36, 'Article 36', 'Article 36', 'Contenu standard de l''article 36 des statuts de l''AMAC. Conformément aux dispositions en vigueur, les membres s''engagent à respecter l''objet de l''association et à participer activement à ses activités pour promouvoir la musique afro-cubaine.', 'TITRE V - ADMINISTRATION ET FONCTIONNEMENT', 'CHAPITRE III - L''ORGANISATION ADMINISTRATIVE', 36);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (37, 1, 37, 'Article 37', 'Création des Sections', 'Il est créé au sein de l''AMAC des sections locales. Chaque section regroupe les membres d''une même localité géographique.', 'TITRE III - DE LA SECTION', NULL, 37);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (38, 1, 38, 'Article 38', 'Aire géographique des Sections', 'Chaque section exerce ses activités sur l''aire géographique définie à l''article 14 des présents statuts, sous la supervision du responsable de section.', 'TITRE III - DE LA SECTION', NULL, 38);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (39, 1, 39, 'Article 39', 'Fonctionnement des Sections', 'Le responsable de section est élu par les membres locaux et rend compte de ses activités au Bureau Exécutif National.', 'TITRE III - DE LA SECTION', NULL, 39);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (40, 1, 40, 'Article 40', 'Article 40', 'Contenu standard de l''article 40 des statuts de l''AMAC. Conformément aux dispositions en vigueur, les membres s''engagent à respecter l''objet de l''association et à participer activement à ses activités pour promouvoir la musique afro-cubaine.', 'TITRE V - RESSOURCES FINANCIERES', NULL, 40);
