INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (44, 1, 44, 'Article 44', 'Proposition de modification', 'Les présents statuts ne peuvent être modifiés que sur proposition des 2/3 du Bureau Exécutif ou de l''Assemblée Générale. L''adoption se fait conformément aux conditions de l''article 20 des statuts.', 'TITRE VI - MODIFICATION DES STATUTS ET DISSOLUTION', NULL, 44);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (45, 1, 45, 'Article 45', 'Article 45', 'Contenu standard de l''article 45 des statuts de l''AMAC. Conformément aux dispositions en vigueur, les membres s''engagent à respecter l''objet de l''association et à participer activement à ses activités pour promouvoir la musique afro-cubaine.', 'TITRE VI - MODIFICATION DES STATUTS ET DISSOLUTION', NULL, 45);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (46, 1, 46, 'Article 46', 'Révision et vote de modification', 'Toute modification des statuts est adoptée à la majorité simple lors de l''assemblée, conformément aux dispositions de l''article 20.', 'TITRE VI - MODIFICATION DES STATUTS ET DISSOLUTION', NULL, 46);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (47, 1, 47, 'Article 47', 'Article 47', 'Contenu standard de l''article 47 des statuts de l''AMAC. Conformément aux dispositions en vigueur, les membres s''engagent à respecter l''objet de l''association et à participer activement à ses activités pour promouvoir la musique afro-cubaine.', 'TITRE VII - DISPOSITIONS FINALES', NULL, 47);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (48, 1, 48, 'Article 48', 'Loi applicable', 'Les présents statuts sont régis par la loi n° 60-315 du 20 septembre 1960 relative aux associations en Côte d''Ivoire.', 'TITRE VII - DISPOSITIONS FINALES', NULL, 48);
