INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (50, 2, 1, 'Article 1', 'Article 1', 'Contenu standard de l''article 1 du règlement intérieur de l''AMAC. Cet article précise les modalités d''application des statuts pour assurer le bon fonctionnement de l''association au quotidien.', 'TITRE I - ADHESION - COTISATIONS', NULL, 1);
