INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (55, 2, 6, 'Article 6', 'Frais de carte de membre', 'Les frais d''acquisition de la carte d''adhérent et le montant de la cotisation mensuelle sont fixés par le Bureau Exécutif National et payables d''avance.', 'TITRE II - DISCIPLINE ET SANCTIONS', NULL, 6);
