INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (65, 2, 16, 'Article 16', 'Procédure d''exclusion', 'En cas d''exclusion d''un membre pour faute grave, la procédure disciplinaire est régie par l''Article 6 ci-dessus, garantissant le droit de parole du membre.', 'TITRE III - DROITS AND DEVOIRS DES MEMBRES', NULL, 16);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (66, 2, 17, 'Article 17', 'Article 17', 'Contenu standard de l''article 17 du règlement intérieur de l''AMAC. Cet article précise les modalités d''application des statuts pour assurer le bon fonctionnement de l''association au quotidien.', 'TITRE III - DROITS AND DEVOIRS DES MEMBRES', NULL, 17);
