INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (69, 2, 20, 'Article 20', 'Scrutins et vote des fondateurs', 'Les membres fondateurs ne disposent pas de droit de vote lors des scrutins de l''assemblée, en conformité avec les statuts.', 'TITRE III - DROITS AND DEVOIRS DES MEMBRES', NULL, 20);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (70, 2, 21, 'Article 21', 'Article 21', 'Contenu standard de l''article 21 du règlement intérieur de l''AMAC. Cet article précise les modalités d''application des statuts pour assurer le bon fonctionnement de l''association au quotidien.', 'TITRE III - DROITS AND DEVOIRS DES MEMBRES', NULL, 21);
