INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (73, 2, 24, 'Article 24', 'Délégation de vote', 'Le vote par procuration est restreint aux membres fondateurs empêchés lors de la réunion de l''assemblée générale.', 'TITRE IV - FONCTIONNEMENT DES ORGANES', 'CHAPITRE I - LE BUREAU EXECUTIF', 24);
INSERT INTO articles (id, texte_id, numero, numero_affiche, titre, contenu_actuel, titre_parent, chapitre, ordre) VALUES (74, 2, 25, 'Article 25', 'Composition du Comité de Contrôle', 'Le Comité de Contrôle est composé exclusivement de membres fondateurs, afin de garantir l''indépendance de leur mission d''audit.', 'TITRE IV - FONCTIONNEMENT DES ORGANES', 'CHAPITRE I - LE BUREAU EXECUTIF', 25);
